INSERT INTO "historical_eras" ("key","name","start_year","end_year","summary") VALUES ('PRE_COLONIAL'::"EraKey", 'Ibaloi Highlands', 1500, 1899, 'Long before it was a city, the cool plateau of Kafagway was home to the Ibaloi people, who farmed sweet potato, panned gold, and pastured cattle across the grassy ridges. Clans such as the Cariños held the meadows now covered by Burnham Park and Camp John Hay. Life followed the rhythms of the cañao feast and the dap-ay council, rooted in the land the Ibaloi had tended for centuries.');
INSERT INTO "historical_eras" ("key","name","start_year","end_year","summary") VALUES ('AMERICAN_COLONIAL'::"EraKey", 'American Hill Station', 1900, 1941, 'American authorities, seeking a cool refuge from lowland heat, transformed Kafagway into a planned summer capital. Architect Daniel Burnham''s 1904 design gave the city its park, radial roads, and civic core, while the hand-carved Kennon Road linked it to the lowlands. Chartered in 1909, Baguio grew into the ''City of Pines,'' a hub of government, mining wealth, and mountain leisure.');
INSERT INTO "historical_eras" ("key","name","start_year","end_year","summary") VALUES ('POST_WAR'::"EraKey", 'Liberation and Rebuilding', 1942, 1989, 'The Second World War devastated Baguio, from the 1941 bombings to the fierce 1945 battle that leveled much of the city and ended with General Yamashita''s surrender nearby. In the decades that followed, residents rebuilt the cathedral, markets, and schools, and the city reclaimed its role as an educational and tourist center. Universities, convents, and craft cooperatives flourished across the recovering hills.');
INSERT INTO "historical_eras" ("key","name","start_year","end_year","summary") VALUES ('MODERN'::"EraKey", 'Contemporary Baguio', 1990, NULL, 'The 1990 Luzon earthquake tested the city anew, but Baguio rebuilt and reinvented itself as a center of culture, cuisine, and creativity. Malls, art villages, and the annual Panagbenga Flower Festival now draw millions, even as residents grapple with congestion and the loss of pines. In 2017 UNESCO named it a Creative City of Crafts and Folk Art, honoring its living Cordillera heritage.');
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('c610db72-740f-5dcd-bbca-21e348ea8391', 'burnham-park', 'Burnham Park', 'The green heart of Baguio, laid out to Daniel Burnham''s 1904 city plan around a man-made lagoon where visitors paddle rented boats. Its tree-lined lanes, rose garden, and skating rink draw families and cyclists at every hour. On cool mornings the melody of buskers and the scent of pine define the city''s leisurely rhythm.', 'PARK'::"Category", 1442, NULL, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.5936, 16.4116), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('2ea6042c-3f31-57e4-bbaa-1c1a32cfa55a', 'session-road', 'Session Road', 'Baguio''s sloping main artery, lined with cafes, bookshops, bakeries, and department stores that climb toward the cathedral steps. Named for the American colonial commission sessions once held here, it remains the commercial and social spine of the city. During festivals the whole street closes to traffic for the celebrated Session Road in Bloom.', 'HERITAGE'::"Category", 1449, NULL, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.5967, 16.4118), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('300b6813-b007-5339-bf23-83369c9d88a4', 'mines-view-park', 'Mines View Park', 'A dramatic overlook perched on the city''s eastern ridge, gazing across the abandoned gold and copper mines of Itogon toward the Amburayan valleys. Souvenir stalls, rented Igorot attire, and St. Bernard photo dogs crowd the viewing deck. At dawn the mountains below fill with a sea of clouds that gives the park its enduring fame.', 'VIEWPOINT'::"Category", 1523, '{"open":"06:00","close":"20:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.628, 16.4201), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('79812191-333a-5e66-93e0-d8eab4d1281a', 'camp-john-hay', 'Camp John Hay', 'A former American rest-and-recreation base turned forested leisure estate, blanketed in some of the tallest pine stands in the city. Today it holds golf links, the Bell House, the Cemetery of Negativism, and a treetop adventure park. Its cool, resin-scented trails make it the favorite escape of both locals and honeymooners.', 'RECREATION'::"Category", 1503, '{"open":"07:00","close":"22:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.618, 16.401), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('522f1fa2-642b-5747-8baf-45582e899c7b', 'baguio-cathedral', 'Our Lady of the Atonement Cathedral', 'The rose-pink cathedral crowning Mount Mary, reached by a long flight of steps from Session Road. Its twin spires became a shelter during the 1945 Battle of Baguio and a symbol of the city''s postwar resilience. From its plaza visitors catch sweeping views over the downtown rooftops.', 'CHURCH'::"Category", 1453, '{"open":"05:00","close":"20:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.5961, 16.4132), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('fd16acba-baa1-5992-b542-0ad717586f68', 'wright-park', 'Wright Park', 'A formal reflecting pool known as the Pool of Pines runs the length of this elegant park facing The Mansion gates. At its lower end the Pony Boys offer horseback rides along shaded circuits beloved by children. Named for Governor-General Luke Wright, it is one of Baguio''s most photographed colonial-era landscapes.', 'PARK'::"Category", 1448, '{"open":"06:00","close":"19:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.6215, 16.409), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('6f715f34-2a50-5a60-adce-8d978fbe7f86', 'the-mansion', 'The Mansion', 'The official summer residence of the President of the Philippines, built in 1908 and guarded by an ornate wrought-iron gate said to echo Buckingham Palace. Its manicured lawns and reflecting fountain sit directly across from Wright Park. Visitors may photograph the grounds and view the small exhibit hall near the entrance.', 'HERITAGE'::"Category", 1466, '{"open":"08:00","close":"17:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.623, 16.4085), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('a387116d-2994-554c-a059-6fc080761543', 'botanical-garden', 'Baguio Botanical Garden', 'A lush terraced garden along Leonard Wood Road showcasing native pine, ferns, and Cordillera flora amid stone huts and Igorot woodcarvings. Once called the Igorot Village, it honors the highland communities who shaped the region''s culture. Its shaded paths and small waterfalls offer a quiet counterpoint to the busy parks nearby.', 'NATURE'::"Category", 1501, '{"open":"06:00","close":"18:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.6178, 16.416), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('90f89ddb-ff41-50e6-9c9d-34bc498d5aaa', 'baguio-public-market', 'Baguio City Public Market', 'A sprawling, labyrinthine market where highland farmers sell strawberries, sweet peas, ube, and mountain vegetables at cool-climate freshness. Sections for weavings, silver, brooms, and peanut brittle make it the city''s essential pasalubong destination. The damp, fragrant aisles capture Baguio''s role as the trading hub of the Cordillera.', 'MARKET'::"Category", 1482, '{"open":"05:00","close":"19:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.593, 16.4155), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('6d569310-f22e-5deb-94ef-a6618e1d6010', 'tam-awan-village', 'Tam-awan Village', 'A reconstructed cluster of authentic Ifugao and Kalinga huts climbing a forested hillside, conceived by artists as a living gallery of Cordillera heritage. Winding trails lead past dap-ay stone circles to a summit that, on clear days, frames the South China Sea. Its cafe and workshops make it a hub for indigenous art and slow travel.', 'HERITAGE'::"Category", 1476, '{"open":"08:00","close":"18:00"}'::jsonb, 'MODERN'::"EraKey", ST_SetSRID(ST_MakePoint(120.576, 16.431), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('527bafad-cf0b-53e1-943a-33ec3c7b0b63', 'bencab-museum', 'BenCab Museum', 'The hillside museum of National Artist Benedicto Cabrera along Asin Road, overlooking a misty ravine and eco-trail. Its galleries pair BenCab''s own paintings with an outstanding collection of Cordillera bulul figures and tribal artifacts. A farm-to-table cafe and duck pond below make it a full afternoon''s immersion in art and mountain air.', 'MUSEUM'::"Category", 979, '{"open":"09:00","close":"18:00"}'::jsonb, 'MODERN'::"EraKey", ST_SetSRID(ST_MakePoint(120.549, 16.382), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('a9a8779c-385b-5c3e-a865-e09df019ca86', 'philippine-military-academy', 'Philippine Military Academy', 'The premier training school of the Armed Forces of the Philippines, set on the broad Fort del Pilar grounds in southern Baguio. Visitors watch cadet formations, tour the grave of the Igorot spirit Mateo Cariño, and browse the Melchor Hall military museum. The disciplined parade grounds and pine borders embody the academy''s storied prestige.', 'HERITAGE'::"Category", 1359, '{"open":"08:00","close":"17:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.618, 16.362), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('a0e67914-8a60-5a21-b9bd-edeeb893e686', 'la-trinidad-strawberry-farms', 'La Trinidad Strawberry Farms', 'The famed berry fields of the Benguet capital just north of Baguio, where visitors pick their own strawberries straight from the rows. Between harvests the terraced plots supply the region''s markets and the celebrated strawberry taho and ice cream. The nearby StoBoSa hillside houses, painted in bright colors, add a vivid backdrop to the farm visit.', 'NATURE'::"Category", 1332, '{"open":"06:00","close":"18:00"}'::jsonb, 'MODERN'::"EraKey", ST_SetSRID(ST_MakePoint(120.587, 16.464), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('473e5804-512b-5300-90bc-bee08352ce51', 'lourdes-grotto', 'Lourdes Grotto', 'A revered Marian shrine reached by a penitential climb of 252 steps to a hilltop candle-lit sanctuary. Devotees ascend especially during Holy Week, when the winding stairway fills with pilgrims and lit tapers. The summit rewards visitors with a panorama over Kennon Road and the western ridges of the city.', 'CHURCH'::"Category", 1430, '{"open":"05:00","close":"20:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.585, 16.411), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('c91dedfb-30fc-51ce-978b-bdd876ccf54f', 'diplomat-hotel-ruins', 'Diplomat Hotel Ruins', 'The roofless white shell of a 1910s Dominican seminary atop Dominican Hill, later a hotel and now one of Baguio''s most storied haunted landmarks. Wartime executions and abandonment left it steeped in local ghost lore, drawing curious visitors and paranormal seekers. Its arched corridors and hilltop cross command a striking view over the city.', 'HERITAGE'::"Category", 1523, '{"open":"07:00","close":"18:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.58, 16.409), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('2928770f-545e-5c03-bc0e-3ed3f196e8ca', 'good-shepherd-convent', 'Good Shepherd Convent', 'A hilltop convent near Mines View run by the Good Shepherd Sisters, famed for the ube jam and strawberry preserves made by the nuns and their students. Proceeds fund scholarships for Cordillera youth, so the long pasalubong queues carry a charitable purpose. The tranquil grounds and viewpoint make it a serene stop on the Mines View circuit.', 'HERITAGE'::"Category", 1550, '{"open":"07:00","close":"17:00"}'::jsonb, 'POST_WAR'::"EraKey", ST_SetSRID(ST_MakePoint(120.625, 16.4205), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('85883bf1-74a5-5e54-a929-267036a11bb8', 'lions-head-kennon-road', 'Lion''s Head, Kennon Road', 'A massive lion carved from a limestone outcrop by Lions Club sculptors, guarding the winding descent of historic Kennon Road. It marks the traditional gateway to Baguio for travelers ascending from the lowlands of Pangasinan. The pullout offers a dramatic viewpoint over the gorge that the 1900s road builders famously carved by hand.', 'VIEWPOINT'::"Category", 1298, NULL, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.606, 16.341), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('1cf3c077-194b-5004-8fa7-747d8ce18ccf', 'igorot-stone-kingdom', 'Igorot Stone Kingdom', 'A hillside maze of dry-stone terraces, arches, and caves built to honor Cordillera stone-craft and highland mythology. Visitors climb through winding rock passages to viewpoints that celebrate Igorot heritage and engineering. The whimsical, castle-like complex has become a popular modern attraction near Gibraltar Road.', 'RECREATION'::"Category", 1521, '{"open":"07:00","close":"18:00"}'::jsonb, 'MODERN'::"EraKey", ST_SetSRID(ST_MakePoint(120.621, 16.418), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('2cf3c34e-890e-5450-aaa0-0c09eee448bd', 'baguio-city-hall', 'Baguio City Hall', 'The stately seat of the city government, fronted by a landscaped garden and a memorial to the city''s founders. Its clean colonial lines and central location make it a familiar civic landmark between Burnham Park and the market. Seasonal displays and the annual Panagbenga floats often gather along its frontage.', 'HERITAGE'::"Category", 1487, '{"open":"08:00","close":"17:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.6005, 16.4095), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('b63df724-3a4a-5a43-9a56-6ccdb9cea459', 'teachers-camp', 'Teachers Camp', 'A rambling campus of wooden dormitories and halls established in 1908 for the training of American-era teachers. Shaded by towering pines along Leonard Wood Road, it still hosts conventions, scout jamborees, and summer workshops. Its creaking heritage buildings are treasured for both their history and their famous ghost stories.', 'HERITAGE'::"Category", 1464, '{"open":"07:00","close":"18:00"}'::jsonb, 'AMERICAN_COLONIAL'::"EraKey", ST_SetSRID(ST_MakePoint(120.6155, 16.4125), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('34aac0e4-7561-545c-be46-27b40abdb3c6', 'baguio-museum', 'Baguio Museum', 'The regional museum near Governor Pack Road tracing the Ibaloi, Kankanaey, and other Cordillera peoples through textiles, tools, and ritual objects. Dioramas and photographs recount the city''s founding, the mining era, and wartime devastation. It offers an ideal primer on the highland cultures that surround the city.', 'MUSEUM'::"Category", 1473, '{"open":"09:00","close":"17:00"}'::jsonb, 'POST_WAR'::"EraKey", ST_SetSRID(ST_MakePoint(120.6035, 16.4078), 4326));
INSERT INTO "destinations" ("id","slug","name","description","category","elevation_m","hours","era_key","geom") VALUES ('96d9f8b4-39df-50d5-b79d-5ecea440ad34', 'mile-hi-cjh-viewdeck', 'Mile-Hi Viewdeck, Camp John Hay', 'A breezy overlook at the Mile-Hi Center within Camp John Hay, framing rows of towering pines and the eastern mountains. Cafes, an ice-skating rink, and the Camp John Hay Yellow Trail radiate from the deck. It is a favored gathering point for sunset watchers and treetop-adventure visitors.', 'VIEWPOINT'::"Category", 1502, '{"open":"07:00","close":"21:00"}'::jsonb, 'MODERN'::"EraKey", ST_SetSRID(ST_MakePoint(120.613, 16.4045), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('bb0657fb-fa8c-5ad8-bd97-fa4307626404', 'PRE_COLONIAL'::"EraKey", 'Ibaloi Settlement of Kafagway', 1700, 'Ibaloi clans settled the grassy plateau they called Kafagway, herding cattle and panning gold along the streams. The meadows that would become Burnham Park served as communal pasture for families like the Cariños.', ST_SetSRID(ST_MakePoint(120.5936, 16.4116), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('4a5300bb-5192-5b0d-bb6c-16ec0e7852ed', 'PRE_COLONIAL'::"EraKey", 'Spanish Comandancia at La Trinidad', 1846, 'Spanish colonizers established a military comandancia in the neighboring La Trinidad valley, named for the wife of Governor Oscariz. Their reach over the highland Igorot communities remained thin and contested.', ST_SetSRID(ST_MakePoint(120.587, 16.46), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('35a249ae-7894-5c37-876e-4f70567285fe', 'AMERICAN_COLONIAL'::"EraKey", 'American Occupation of the Highlands', 1900, 'Following the Philippine-American War, U.S. forces reached the cool Benguet plateau and quickly recognized its value as a health resort. Plans began for a summer capital that could relieve officials from the lowland heat.', ST_SetSRID(ST_MakePoint(120.5965, 16.411), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('bbbe462e-0d66-5527-bc85-6d6beed91983', 'AMERICAN_COLONIAL'::"EraKey", 'Construction of the Benguet (Kennon) Road', 1903, 'Engineer Lyman Kennon drove the perilous zigzag road up the Bued River gorge, at great cost in labor and lives. The route opened Baguio to wheeled traffic and remains a monument to early American engineering.', ST_SetSRID(ST_MakePoint(120.606, 16.341), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('83ffd12d-8da2-5569-993f-97c1fad0c8bb', 'AMERICAN_COLONIAL'::"EraKey", 'Burnham Plan for the Summer Capital', 1904, 'Architect Daniel Hudson Burnham surveyed the plateau and drafted a city plan centered on a park, a civic core, and radiating avenues. His vision shaped the layout of Baguio that endures today.', ST_SetSRID(ST_MakePoint(120.595, 16.41), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('dd0ca635-5ab4-5c01-8885-f3e5394d5627', 'AMERICAN_COLONIAL'::"EraKey", 'Establishment of Camp John Hay', 1903, 'The U.S. Army set aside a forested reservation as a rest-and-recreation base, naming it for Secretary of State John Hay. Its pine slopes became a retreat for American soldiers and, later, generations of Filipino visitors.', ST_SetSRID(ST_MakePoint(120.618, 16.401), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('1c9462bf-2a5f-58dc-a840-9adbbbdcf813', 'AMERICAN_COLONIAL'::"EraKey", 'Chartering of the City of Baguio', 1909, 'On 1 September 1909 the Philippine Commission granted Baguio its city charter, making it the official summer capital of the islands. The designation cemented its role in national governance for decades.', ST_SetSRID(ST_MakePoint(120.6005, 16.4095), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('9e3e2f30-ae3a-52a9-b07a-e40b771d8c59', 'AMERICAN_COLONIAL'::"EraKey", 'Founding of the Philippine Military Academy', 1936, 'The Philippine Military Academy was formally organized to train the officer corps of the new Commonwealth army. It settled at Fort del Pilar in southern Baguio, where it still educates the nation''s cadets.', ST_SetSRID(ST_MakePoint(120.618, 16.362), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('b30896e7-ae0e-5aaa-85e2-71c28094fb70', 'POST_WAR'::"EraKey", 'Japanese Bombing and Occupation', 1941, 'On 8 December 1941 Japanese aircraft bombed Camp John Hay hours after Pearl Harbor, among the first strikes on the Philippines. Baguio soon fell under a harsh occupation that lasted until liberation.', ST_SetSRID(ST_MakePoint(120.618, 16.401), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('6e5fca43-5dd2-5809-90c5-d90e76d0d365', 'POST_WAR'::"EraKey", 'Battle and Liberation of Baguio', 1945, 'Intense fighting and Allied bombardment in early 1945 reduced much of the city to rubble as forces closed on General Yamashita''s mountain redoubt. The cathedral''s basement sheltered civilians through the siege.', ST_SetSRID(ST_MakePoint(120.5961, 16.4132), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('f6cecdf8-9bb0-505a-815b-8d4b3cee8537', 'POST_WAR'::"EraKey", 'Surrender of General Yamashita', 1945, 'On 3 September 1945 General Tomoyuki Yamashita formally surrendered at the U.S. ambassador''s residence within Camp John Hay. The ceremony marked the end of the war in the Philippine highlands.', ST_SetSRID(ST_MakePoint(120.613, 16.4045), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('2b9a06a3-1b86-575a-8476-9ecbc3323dfc', 'POST_WAR'::"EraKey", 'Postwar Rebuilding of the Public Market', 1950, 'Residents reconstructed the ruined public market and civic buildings, restoring Baguio as the trading heart of the Cordillera. Highland farmers again filled the stalls with vegetables, strawberries, and weavings.', ST_SetSRID(ST_MakePoint(120.593, 16.4155), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('eab434b0-0228-56c6-b20c-89e6ad59bfb3', 'POST_WAR'::"EraKey", 'Rise of the University Town', 1965, 'Universities and colleges expanded across the city, drawing students from throughout northern Luzon. Education became a pillar of the local economy alongside tourism and mining.', ST_SetSRID(ST_MakePoint(120.5967, 16.4118), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('dc357ea0-4244-5ea7-8fa7-0013164c4a9b', 'MODERN'::"EraKey", 'The 1990 Luzon Earthquake', 1990, 'A magnitude 7.8 earthquake on 16 July 1990 collapsed hotels and buildings, killing hundreds and isolating the city for days. Baguio''s determined recovery became a defining chapter of its modern history.', ST_SetSRID(ST_MakePoint(120.5967, 16.4118), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('4c125f50-9154-508b-9b05-3e3fcbd72f6a', 'MODERN'::"EraKey", 'First Panagbenga Flower Festival', 1996, 'Launched to lift civic spirits after the earthquake, the Panagbenga Flower Festival filled Session Road with floral floats and street dancers. It has grown into the city''s signature February celebration.', ST_SetSRID(ST_MakePoint(120.5967, 16.4118), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('3432ea87-5511-5c78-9424-e6d1ba40440f', 'MODERN'::"EraKey", 'Opening of SM City Baguio', 2003, 'The opening of SM City Baguio brought large-scale retail to the city and reshaped its commercial landscape. The mall drew crowds but also stirred debate over pine trees and mountain congestion.', ST_SetSRID(ST_MakePoint(120.599, 16.4085), 4326));
INSERT INTO "historical_events" ("id","era_key","title","year","description","geom") VALUES ('12ba6026-5b3d-5cfc-af9f-71672892f57f', 'MODERN'::"EraKey", 'UNESCO Creative City of Crafts and Folk Art', 2017, 'UNESCO named Baguio a Creative City for its living traditions of weaving, woodcarving, silverwork, and tattoo art. The honor affirmed the enduring vitality of Cordillera culture in the modern city.', ST_SetSRID(ST_MakePoint(120.576, 16.431), 4326));
INSERT INTO "transit_routes" ("id","code","name","kind","fare_base","fare_per_km","geom") VALUES ('ec492e77-bef7-56d3-bf33-e239df0e3473', 'PLZ-MVP', 'Plaza - Mines View Park', 'JEEPNEY'::"TransitKind", 13, 1.8, ST_SetSRID(ST_GeomFromGeoJSON('{"type":"LineString","coordinates":[[120.5965,16.411],[120.5976,16.4114],[120.599,16.4118],[120.6008,16.4122],[120.603,16.4129],[120.6056,16.4134],[120.6082,16.4141],[120.6108,16.4149],[120.6133,16.4155],[120.6158,16.4161],[120.6183,16.4168],[120.6208,16.4176],[120.6233,16.4185],[120.6254,16.4192],[120.6269,16.4198],[120.628,16.4201]]}'), 4326));
