INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('5ab9df50-6fdc-53d9-b0ef-a93d7812c6ca', 'cafe-by-the-ruins', 'Cafe by the Ruins', 'RESTAURANT'::"VenueCategory", 3, '["farm-to-table","native coffee","bakery","art space"]'::jsonb, '{"open":"07:00","close":"21:00"}'::jsonb, 'A beloved institution serving Cordillera-inspired dishes, tapuy rice wine, and rustic bread beside the old ruins downtown. Its garden-fresh cooking helped define Baguio''s slow-food identity.', ST_SetSRID(ST_MakePoint(120.597, 16.4125), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('b8db20e5-6044-5f53-8efc-c0ea68951a4b', 'hill-station', 'Hill Station', 'RESTAURANT'::"VenueCategory", 3, '["wine list","global cuisine","heritage building","reservations"]'::jsonb, '{"open":"08:00","close":"22:00"}'::jsonb, 'A candle-lit restaurant inside historic Casa Vallejo blending Filipino, Spanish, and Asian flavors along old trade routes. Its refined plates and cozy interiors make it a favorite for special evenings.', ST_SetSRID(ST_MakePoint(120.5945, 16.4095), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('848be82c-38ef-58b4-8749-c0e0456156ea', 'good-taste', 'Good Taste Cafe and Restaurant', 'RESTAURANT'::"VenueCategory", 1, '["24-hours","large portions","group dining","budget-friendly"]'::jsonb, NULL, 'A cavernous, always-open eatery famous for enormous portions of buttered chicken and fried rice at rock-bottom prices. It is the go-to refuel stop for hungry travelers at any hour.', ST_SetSRID(ST_MakePoint(120.5945, 16.414), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('664d5130-6408-5e8e-b92b-95d2541e6fa9', 'oh-my-gulay', 'Oh My Gulay', 'RESTAURANT'::"VenueCategory", 2, '["vegetarian","art gallery","top-floor views","cash only"]'::jsonb, '{"open":"11:00","close":"20:00"}'::jsonb, 'An artist-run vegetarian cafe crowning the La Azotea building, filled with whimsical installations and a koi pond. Its meat-free plates and creative ambience draw students and bohemians alike.', ST_SetSRID(ST_MakePoint(120.597, 16.413), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('fed15eb5-b85f-5d85-9046-8b167d436099', '50s-diner', '50''s Diner', 'RESTAURANT'::"VenueCategory", 2, '["retro theme","all-day breakfast","milkshakes","family-friendly"]'::jsonb, '{"open":"07:00","close":"22:00"}'::jsonb, 'A nostalgic American-style diner on Leonard Wood Road serving hearty breakfasts, burgers, and thick milkshakes. Its jukebox decor and generous plates make it a long-running local favorite.', ST_SetSRID(ST_MakePoint(120.608, 16.414), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('0298f8eb-8bd6-5117-934b-67cb73a3d1bd', 'canto-bogchi-joint', 'Canto Bogchi Joint', 'RESTAURANT'::"VenueCategory", 2, '["ribs specialty","casual","local favorite"]'::jsonb, '{"open":"11:00","close":"21:00"}'::jsonb, 'A casual grill renowned for its tender rib platters and comforting rice bowls. Locals prize it as one of the city''s best-value comfort-food stops.', ST_SetSRID(ST_MakePoint(120.609, 16.415), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('906ee08a-44ae-5540-a22a-5ae8697a4f6c', 'amare-la-cucina', 'Amare La Cucina', 'RESTAURANT'::"VenueCategory", 2, '["wood-fired pizza","italian","pet-friendly"]'::jsonb, '{"open":"11:00","close":"22:00"}'::jsonb, 'A cozy trattoria turning out wood-fired Neapolitan pizzas and hearty pasta in the cool mountain air. Its authentic Italian fare has earned a devoted following.', ST_SetSRID(ST_MakePoint(120.607, 16.4145), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('7ec7c8ef-69b4-5f23-8fbf-146e534c75c4', 'lemon-and-olives', 'Lemon and Olives Greek Taverna', 'RESTAURANT'::"VenueCategory", 3, '["greek cuisine","hilltop views","reservations"]'::jsonb, '{"open":"11:00","close":"21:00"}'::jsonb, 'The city''s only Greek taverna, perched on Outlook Drive with sweeping ridge views and authentic Mediterranean plates. Its souvlaki and moussaka offer a sunlit change of pace.', ST_SetSRID(ST_MakePoint(120.623, 16.419), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('abcbb4f8-6313-549b-90b5-2e1991bb09e6', 'ketchup-food-community', 'Ketchup Food Community', 'RESTAURANT'::"VenueCategory", 2, '["food cluster","forest setting","varied cuisines"]'::jsonb, '{"open":"10:00","close":"21:00"}'::jsonb, 'A cluster of independent eateries sharing a pine-shaded compound on Romulo Drive near Wright Park. Diners can graze across Filipino, Mexican, and grilled specialties in one leafy setting.', ST_SetSRID(ST_MakePoint(120.614, 16.4095), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('a21adf29-f348-5fd5-bfec-f005cd539b46', 'vizcos', 'Vizco''s Restaurant and Cake Shop', 'FOOD_SHOP'::"VenueCategory", 2, '["strawberry shortcake","cakes","dine-in","takeaway"]'::jsonb, '{"open":"09:00","close":"21:00"}'::jsonb, 'A Session Road bakeshop famed for its towering strawberry shortcake made with fresh Benguet berries. Its cakes are among the city''s most popular edible pasalubong.', ST_SetSRID(ST_MakePoint(120.5968, 16.4125), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('768f2ac9-d430-5c25-8d62-736915517ff1', 'good-shepherd-ube-jam', 'Good Shepherd Convent Store', 'FOOD_SHOP'::"VenueCategory", 2, '["ube jam","strawberry preserves","peanut brittle","charity proceeds"]'::jsonb, '{"open":"07:30","close":"17:00"}'::jsonb, 'The convent store beside Mines View selling the nuns'' celebrated ube halaya, strawberry jam, and peanut brittle. Every jar funds scholarships for Cordillera students.', ST_SetSRID(ST_MakePoint(120.6245, 16.42), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('6020361d-6955-54a4-870f-e8ba2cb2c880', 'baguio-country-club-bakeshop', 'Baguio Country Club Bakeshop', 'FOOD_SHOP'::"VenueCategory", 3, '["raisin bread","cheese bread","pastries"]'::jsonb, '{"open":"07:00","close":"19:00"}'::jsonb, 'The historic club''s bakeshop, whose warm raisin bread is a legendary Baguio pasalubong. Visitors line up for loaves fresh from the oven.', ST_SetSRID(ST_MakePoint(120.616, 16.4), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('e95daef4-8981-5347-b7f0-35940cbe9966', 'choco-late-de-batirol', 'Choco-late de Batirol', 'FOOD_SHOP'::"VenueCategory", 2, '["native hot chocolate","garden cafe","kakanin"]'::jsonb, '{"open":"08:00","close":"20:00"}'::jsonb, 'A garden cafe in Camp John Hay serving thick native tsokolate whisked the traditional way with a batirol. Its cozy nipa huts pair the drink with Filipino rice cakes.', ST_SetSRID(ST_MakePoint(120.613, 16.405), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('8de1e072-5f6c-5a47-9e1c-6a67f0ba1179', 'mines-view-souvenir-row', 'Mines View Souvenir Row', 'SOUVENIR'::"VenueCategory", 1, '["woodcarvings","knitwear","walking sticks","keychains"]'::jsonb, '{"open":"07:00","close":"19:00"}'::jsonb, 'The dense stretch of stalls beside Mines View Park brimming with knitted bonnets, wooden crafts, and trinkets. It is the classic spot for last-minute Baguio keepsakes.', ST_SetSRID(ST_MakePoint(120.6275, 16.42), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('436bd55d-d991-5485-8864-508f48b8ca05', 'easter-weaving-room', 'Easter Weaving Room', 'SOUVENIR'::"VenueCategory", 2, '["handwoven textiles","loom demonstrations","bags","table runners"]'::jsonb, '{"open":"08:00","close":"17:00"}'::jsonb, 'A century-old weaving center in Guisad where visitors watch artisans work traditional looms. Its handwoven Cordillera textiles, bags, and blankets support local weavers.', ST_SetSRID(ST_MakePoint(120.585, 16.42), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('4b3d9c31-3f6d-5a52-a958-2462c0e2dd3f', 'ibays-silver-shop', 'Ibay''s Silver Shop', 'SOUVENIR'::"VenueCategory", 2, '["silver jewelry","custom pieces","Cordillera motifs"]'::jsonb, '{"open":"09:00","close":"18:00"}'::jsonb, 'A long-established silversmith crafting jewelry inspired by Cordillera patterns and symbols. Its handmade rings and pendants are treasured Baguio mementos.', ST_SetSRID(ST_MakePoint(120.596, 16.412), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('77feddca-c0b3-5a58-802e-121007cd73a9', 'nardas-handwoven', 'Narda''s Handwoven Arts and Crafts', 'SOUVENIR'::"VenueCategory", 3, '["premium textiles","shawls","home decor","fashion"]'::jsonb, '{"open":"09:00","close":"18:00"}'::jsonb, 'A pioneering weaving house whose ikat-dyed shawls and garments carry Cordillera craft into contemporary fashion. Its refined pieces are gifted and worn nationwide.', ST_SetSRID(ST_MakePoint(120.602, 16.413), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('0c764d49-eeae-5863-b0dc-b6f5d9bc5767', 'public-market-pasalubong', 'Public Market Pasalubong Stalls', 'SOUVENIR'::"VenueCategory", 1, '["dried fruit","coffee","brooms","peanut brittle","vegetables"]'::jsonb, '{"open":"06:00","close":"18:00"}'::jsonb, 'The pasalubong section of the public market packed with strawberry preserves, highland coffee, and native brooms. It is the most affordable place to stock up on Baguio treats.', ST_SetSRID(ST_MakePoint(120.593, 16.415), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('255488ca-5e66-55d2-a34a-1c66c1bc762a', 'the-manor-cjh', 'The Manor at Camp John Hay', 'HOTEL'::"VenueCategory", 4, '["fireplace lobby","spa","fine dining","pine forest","parking"]'::jsonb, NULL, 'The flagship luxury hotel of Camp John Hay, styled like a grand alpine lodge amid towering pines. Its log-and-stone interiors and cozy fireplaces epitomize upscale mountain retreat.', ST_SetSRID(ST_MakePoint(120.615, 16.403), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('3f0764e4-b173-5e1c-b90a-1ab3e7ae9aff', 'forest-lodge-cjh', 'Forest Lodge at Camp John Hay', 'HOTEL'::"VenueCategory", 3, '["forest views","restaurant","family rooms","parking"]'::jsonb, NULL, 'A comfortable pine-side lodge within Camp John Hay offering easy access to the golf course and trails. Its warm rooms suit families and groups seeking a forest escape.', ST_SetSRID(ST_MakePoint(120.6155, 16.4035), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('5cc2d3b7-ddad-586a-9e9a-3d8861b0b553', 'hotel-elizabeth', 'Hotel Elizabeth Baguio', 'HOTEL'::"VenueCategory", 3, '["restaurant","function rooms","shuttle","parking"]'::jsonb, NULL, 'A gracious mid-range hotel on Gibraltar Road with colonial-inspired decor and a well-regarded restaurant. Its quiet ridge location is close to Mines View and Wright Park.', ST_SetSRID(ST_MakePoint(120.618, 16.415), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('5205431c-0edd-5846-afe4-6b5fa68f17b7', 'microtel-baguio', 'Microtel by Wyndham Baguio', 'HOTEL'::"VenueCategory", 3, '["city views","24-hour front desk","restaurant","parking"]'::jsonb, NULL, 'A dependable upper-Session hotel offering clean, comfortable rooms with sweeping views over the downtown bowl. Its central location puts the market and Burnham Park within easy reach.', ST_SetSRID(ST_MakePoint(120.592, 16.408), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('058687ce-4b39-5d42-8fca-6dc8725516ad', 'baguio-country-club', 'Baguio Country Club', 'HOTEL'::"VenueCategory", 4, '["golf course","bowling","spa","heritage","fine dining"]'::jsonb, NULL, 'A prestigious members'' club and hotel dating to 1905, set on manicured grounds beside a historic golf course. Its heritage halls and famous bakeshop make it a Baguio landmark in their own right.', ST_SetSRID(ST_MakePoint(120.616, 16.4005), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('2db4fa7a-a5fe-516d-8c8f-46957507d02f', 'casa-vallejo', 'Casa Vallejo', 'HOTEL'::"VenueCategory", 3, '["heritage building","bookshop","cinema","restaurant"]'::jsonb, NULL, 'The city''s oldest surviving hotel, a 1909 wooden landmark at the top of Session Road with creaking floors and vintage charm. It shares its walls with an indie cinema, bookshop, and Hill Station restaurant.', ST_SetSRID(ST_MakePoint(120.5945, 16.4096), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('2a52d5ba-d4ce-5cb1-bfc2-a61892f995fe', 'azalea-residences', 'Azalea Residences Baguio', 'HOTEL'::"VenueCategory", 3, '["kitchenette suites","cafe","playground","parking"]'::jsonb, NULL, 'An apartment-style hotel on Leonard Wood Loop offering suites with kitchenettes for longer family stays. Its quiet residential setting is a short ride from downtown attractions.', ST_SetSRID(ST_MakePoint(120.598, 16.42), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('9e73b643-8aec-5982-8ad6-94b4d50e8a13', 'pine-breeze-transient', 'Pine Breeze Transient House', 'TRANSIENT'::"VenueCategory", 1, '["shared kitchen","group rooms","wifi","parking"]'::jsonb, NULL, 'A budget transient home in Aurora Hill with roomy shared quarters popular among student and family groups. Guests cook their own meals and enjoy a homey mountain base.', ST_SetSRID(ST_MakePoint(120.605, 16.423), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('57328cdd-6f3e-5978-9e54-b7c8bc339e81', 'cordillera-family-transient', 'Cordillera Family Transient', 'TRANSIENT'::"VenueCategory", 1, '["whole-house rental","kitchen","family-friendly","parking"]'::jsonb, NULL, 'A homey Guisad transient house rented whole for reunions and barkada trips. Its full kitchen and living room give large groups an affordable home away from home.', ST_SetSRID(ST_MakePoint(120.589, 16.425), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('20833b13-c85e-5e25-8898-5de838de8e13', 'session-road-backpackers', 'Session Road Backpackers', 'TRANSIENT'::"VenueCategory", 2, '["dorm beds","common lounge","wifi","central location"]'::jsonb, NULL, 'A compact hostel steps from Session Road offering bunk beds and a sociable common lounge. Its central spot suits solo travelers exploring the downtown core on foot.', ST_SetSRID(ST_MakePoint(120.5965, 16.4135), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('555e553e-4f33-583d-8956-6401af7a6aa0', 'mountain-view-transient', 'Mountain View Transient', 'TRANSIENT'::"VenueCategory", 1, '["ridge views","kitchen","group rooms","parking"]'::jsonb, NULL, 'A simple transient house on Gibraltar Road with balconies framing the eastern mountains. Its proximity to Mines View makes it a convenient budget base for sightseeing.', ST_SetSRID(ST_MakePoint(120.622, 16.4185), 4326));
INSERT INTO "venues" ("id","slug","name","category","price_range","amenities","hours","description","geom") VALUES ('01d4ace0-1102-52e5-8ce5-6ca2dee9d0d1', 'strawberry-fields-transient', 'Strawberry Fields Transient', 'TRANSIENT'::"VenueCategory", 1, '["near strawberry farms","kitchen","family rooms","parking"]'::jsonb, NULL, 'A quiet transient house on the La Trinidad edge, minutes from the famous strawberry fields. It offers groups a restful, low-cost stay away from the downtown bustle.', ST_SetSRID(ST_MakePoint(120.588, 16.445), 4326));
