INSERT INTO "districts" ("id","name","geom") VALUES ('b2a2a7c1-3786-5c9f-9657-ab00032a8af4', 'Aurora Hill', ST_SetSRID(ST_GeomFromGeoJSON('{"type":"Polygon","coordinates":[[[120.6005,16.431],[120.609,16.432],[120.6135,16.4275],[120.6125,16.4205],[120.606,16.418],[120.6,16.4205],[120.5985,16.4265],[120.6005,16.431]]]}'), 4326));
